<?php
declare(strict_types=1);
namespace App\Controller;
use App\Form\SimulationActionType;
use App\Service\{DemoDatabase,SimulationEngine,ActionForms};
use Symfony\Bundle\FrameworkBundle\Controller\AbstractController;
use Symfony\Component\Routing\Attribute\Route;
use Symfony\Component\HttpFoundation\{Request,Response,JsonResponse,RedirectResponse};
use Symfony\Component\Form\Extension\Core\Type\{ChoiceType,FileType,SubmitType};
use Symfony\Component\Validator\Constraints as Assert;
final class DemoController extends AbstractController{
 private const VIEWS=['home','territories','proposals','consultations','experiments','convergence','memory','transparency','infrastructure','governance','citizen','charter'];
 private const LABELS=['home'=>'Vue d’ensemble','territories'=>'Les territoires','proposals'=>'Les chemins','consultations'=>'Les consultations','experiments'=>'Les expériences','convergence'=>'La convergence','memory'=>'Mémoire collective','transparency'=>'Transparence','infrastructure'=>'Infrastructure','governance'=>'Gouvernance','citizen'=>'Participer','charter'=>'La charte'];
 public function __construct(private DemoDatabase $database,private SimulationEngine $engine,private string $projectDir){}
 private function owner(Request $r):string{$session=$r->getSession();if(!$session->has('simulation_owner'))$session->set('simulation_owner',bin2hex(random_bytes(24)));return $session->get('simulation_owner');}
 private function context(Request $r,string $view='home'):array{$w=$this->database->workspace($this->owner($r));$s=$this->engine->publicState($w['state']);$actor=$r->getSession()->get('citizen_id','u1');$citizens=array_column($s['citizens'],null,'id');if(!isset($citizens[$actor]))$actor='u1';return ['s'=>$s,'revision'=>$w['revision'],'view'=>$view,'labels'=>self::LABELS,'actor'=>$citizens[$actor],'territoryMap'=>array_column($s['territories'],null,'id'),'citizenMap'=>$citizens,'proposalMap'=>array_column($s['proposals'],null,'id'),'convergence'=>$this->engine->convergence($s),'categories'=>SimulationEngine::CATEGORIES,'guardianPath'=>$_SERVER['GUARDIAN_LOGIN_PATH']??'/demo-profiler-shield-populorum'];}
 #[Route('/',name:'home',methods:['GET'])]
 #[Route('/{view}',name:'section',requirements:['view'=>'territories|proposals|consultations|experiments|convergence|memory|transparency|infrastructure|governance|citizen|charter'],methods:['GET'])]
 public function page(Request $r,string $view='home'):Response{
  $ctx=$this->context($r,$view);$ctx['q']=trim((string)$r->query->get('q',''));$ctx['territory']=(string)$r->query->get('territory','all');$ctx['selected']=(string)$r->query->get('id','');
  if($view==='charter'){$locale=(string)$r->query->get('locale','fr_FR');$dir=dirname($this->projectDir,2).'/docs/translations';$locales=array_map('basename',glob($dir.'/*',GLOB_ONLYDIR));if(!in_array($locale,$locales,true))$locale='fr_FR';$file=$locale==='fr_FR'?dirname($this->projectDir,2).'/CHARTER.md':$dir.'/'.$locale.'/CHARTER.md';$ctx+=['locale'=>$locale,'locales'=>$locales,'charter'=>file_get_contents($file)];}
  return $this->render('pages/'.$view.'.html.twig',$ctx);
 }
 #[Route('/action/{type}',name:'simulation_action',methods:['GET','POST'])]
 public function action(Request $r,string $type):Response{
  if(!isset(ActionForms::TYPES[$type]))throw $this->createNotFoundException();$ctx=$this->context($r,ActionForms::TYPES[$type][1]);$initial=['revision'=>(string)$ctx['revision'],'operationId'=>bin2hex(random_bytes(16)),'territoryId'=>$ctx['actor']['territoryId'],'theme'=>'Mobilités','tags'=>'trafic, accessibilité','forecast'=>0,'days'=>14,'quorum'=>50,'uncertainty'=>5,'reason'=>'Clôture pédagogique volontaire','start'=>gmdate('Y-m-d'),'end'=>gmdate('Y-m-d',time()+90*86400),'date'=>gmdate('Y-m-d'),'unexpected'=>'Aucun imprévu déclaré','bandwidth'=>128,'baseline'=>120,'unit'=>'véhicules / heure'];
  foreach(['proposalId','consultationId','experimentId','governanceId','caseId','nodeId','choice'] as $key)if($r->query->has($key))$initial[$key]=(string)$r->query->get($key);
  if(in_array($type,['proposal.revise','proposal.publish'],true)&&isset($initial['proposalId'])){$q=$ctx['proposalMap'][$initial['proposalId']]??null;if(!$q)throw $this->createNotFoundException();$initial['solution']=$q['solution'];$initial['risk']=$q['risk'];foreach($q['nodes'] as $i=>$n){$initial['node'.$i]=$n['content'];$initial['kind'.$i]=$n['kind'];}}
  if($type==='proposal.create')foreach(SimulationEngine::CATEGORIES as $i=>$category){$initial['node'.$i]=$i===9?'Aucun imprévu observé à ce stade':($i===11?'Première version du chemin':'');$initial['kind'.$i]=$i===4?'observation':'hypothesis';}
  if($type==='citizen.update')$initial['name']=$ctx['actor']['name'];if($type==='citizen.consent')$initial['consent']=false;
  $form=$this->createForm(SimulationActionType::class,$initial,['action_type'=>$type,'territories'=>$ctx['s']['territories']]);$form->handleRequest($r);$error=null;$status=200;
  if($form->isSubmitted()&&$form->isValid()){try{$p=$form->getData();$revision=(int)$p['revision'];$operationId=$p['operationId'];unset($p['revision'],$p['operationId']);$p['citizenId']=$ctx['actor']['id'];if(in_array($type,['proposal.create','proposal.revise'],true)){foreach(SimulationEngine::CATEGORIES as $i=>$category){$p['nodes'][]=['content'=>$p['node'.$i],'kind'=>$p['kind'.$i]];unset($p['node'.$i],$p['kind'.$i]);}}$w=$this->database->workspace($this->owner($r));if($w['revision']!==$revision)throw new \DomainException('La simulation a évolué. Rechargez le formulaire.',409);$next=$this->engine->apply($w['state'],$type,$p,$operationId);$this->database->save($this->owner($r),$revision,$next);$this->addFlash('success','Opération enregistrée dans votre simulation fictive.');return $this->redirectToRoute('section',['view'=>ActionForms::TYPES[$type][1]]);}catch(\DomainException $e){$error=$e->getMessage();$status=$e->getCode()?:400;}}
  elseif($form->isSubmitted())$status=400;
  return $this->render('action.html.twig',$ctx+['form'=>$form->createView(),'title'=>ActionForms::TYPES[$type][0],'type'=>$type,'error'=>$error],new Response(status:$status));
 }
 #[Route('/persona',name:'persona',methods:['POST'])]
 public function persona(Request $r):Response{if(!$this->isCsrfTokenValid('persona',(string)$r->request->get('_token')))throw new \Symfony\Component\HttpKernel\Exception\AccessDeniedHttpException('Jeton CSRF invalide.');$ctx=$this->context($r,'citizen');$id=(string)$r->request->get('citizen');if(!isset($ctx['citizenMap'][$id]))throw $this->createNotFoundException();$r->getSession()->set('citizen_id',$id);return $this->redirectToRoute('section',['view'=>'citizen']);}
 #[Route('/export/{kind}',name:'export',requirements:['kind'=>'memory|proofs|citizen|consultation|experiment'],methods:['GET'])]
 public function export(Request $r,string $kind):Response{$ctx=$this->context($r);$s=$ctx['s'];$payload=$s;$id=(string)$r->query->get('id','');if($kind==='citizen')$payload=['citizen'=>$ctx['actor'],'proposals'=>array_values(array_filter($s['proposals'],fn($q)=>$q['authorId']===$ctx['actor']['id'])),'votes'=>array_values(array_filter($s['votes'],fn($v)=>$v['citizenId']===$ctx['actor']['id']))];if($kind==='consultation'){$cs=array_filter($s['consultations'],fn($c)=>$c['id']===$id);$c=reset($cs);if(!$c)throw $this->createNotFoundException();$payload=$c+['votes'=>array_values(array_filter($s['votes'],fn($v)=>$v['consultationId']===$id))];}if($kind==='experiment'){$items=array_filter($s['experiments'],fn($e)=>$e['id']===$id);$e=reset($items);if(!$e)throw $this->createNotFoundException();$payload=['simulation'=>true,'experiment'=>$e,'proposal'=>$ctx['proposalMap'][$e['proposalId']]];}return new JsonResponse($payload,200,['Cache-Control'=>'no-store','Content-Disposition'=>'attachment; filename="populorum-'.$kind.'.json"','X-Content-Type-Options'=>'nosniff']);}
 #[Route('/verify',name:'verify',methods:['GET','POST'])]
 public function verify(Request $r):Response{$ctx=$this->context($r,'transparency');$result=$this->engine->verify($ctx['s']);$form=$this->createFormBuilder()->add('proof',FileType::class,['label'=>'Export JSON à vérifier','constraints'=>[new Assert\File(maxSize:'5M')]])->add('submit',SubmitType::class,['label'=>'Vérifier cet export'])->getForm();$form->handleRequest($r);if($form->isSubmitted()&&$form->isValid()){try{$v=json_decode(file_get_contents($form->get('proof')->getData()->getPathname()),true,512,JSON_THROW_ON_ERROR);$result=$this->engine->verify($v);}catch(\Throwable){$result=['valid'=>false,'reason'=>'Fichier invalide ou preuve incomplète.'];}}return $this->render('verify.html.twig',$ctx+['result'=>$result,'form'=>$form->createView()]);}
 #[Route('/api/v1/state',name:'api_state',methods:['GET'])]
 public function api(Request $r):Response{$ctx=$this->context($r);return $this->json(['state'=>$ctx['s'],'revision'=>$ctx['revision'],'simulation'=>true],200,['Cache-Control'=>'no-store']);}
}
